{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "Reject. Our position is **25% / $6m**."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Reject. Require **$5,000 de minimis**, **$50,000 aggregate basket**, and a **tipping basket**"
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Reject. Require **24 months post-Completion**."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Fundamental/title claims must have a separate regime: **100% price cap, at least six years**"
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "These must be carved out of **all** caps, thresholds, time bars, exclusive-remedy provisions and non-reliance terms to the maximum enforceable extent."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Reject general/constructive disclosure. Require **specific, fair disclosure** against the relevant warranties."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Delete data-room/public-record deemed disclosure and blanket Buyer-knowledge exclusions."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Completion must require an **effective consent and evidence that every condition to it has been satisfied**."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Reject. Require current payout evidence, **direct repayment from Completion funds**, and effective releases of all Riverlark security at Completion."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Do not permit the funds flow to silently omit this liability."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Broaden the IP indemnity and preserve an effective SOW3 cure mechanism."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Resist any minimisation or disclosure-based exclusion. Require preservation of logs, a documented investigation and continuing updates."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "Sandbar (clause 8):** investigate rather than accept Seller’s categorisation."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Keep Tax, IP, title, payment mechanics and covenant matters separate from the general warranty regime."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "Insist on independent evidence of ownership, authority and absence of encumbrances."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Tax and IP remain **open** and must be separately addressed; there is no accepted unlimited-liability outcome or agreed resolution."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

